const assets = {"/elite/content/BB-37-Elite-Build-851.fwsc": "", "/elite/firmware/bb37-pro.fwsc": "", "/elite/firmware/bb37-mke-p37.fwsc": "", "/elite/content/compas727.bin": "", "/elite/content/hanan-cumbia.bin": "", "/elite/content/layer727.json": ""};
export async function readAsset(key){return Object.hasOwn(assets,key)?new Response(Uint8Array.from(atob(assets[key]), c=>c.charCodeAt(0))):new Response(null,{status:404});}
